mapper.select:
SELECT coop_user_id, p.post_name, m.id, p.related_user_names, p.org_name, m.gmt_created as operate_time, l.name as level_name, p.org_id, p.icon_url FROM tb_coop_level_member m LEFT JOIN tb_collaboration_post p ON m.coop_user_id = p.id LEFT JOIN tb_coop_level l ON m.coop_level_id = l.id WHERE m.is_deleted = 0 and p.deleted = 0 and l.is_deleted = 0 and p.post_name like concat('%', #{name}, '%')
and m.coop_level_id = #{levelId}
AND m.gmt_created >= #{startTime}
AND m.gmt_created <=CONCAT(#{endTime}, ' 23:59:59')
and p.org_id in
#{department}
order by m.gmt_created desc

SELECT coop_user_id, p.post_name, m.id, p.related_user_names, p.org_name, p.operate_time, p.org_id FROM tb_coop_level_member m LEFT JOIN tb_collaboration_post p ON m.coop_user_id = p.id WHERE m.is_deleted = 0 and p.deleted = 0 and m.id in
#{id}
and p.org_id in
#{department}
